schema_ddl:
CREATE TABLE clienti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    data_nascita DATE
);

CREATE TABLE conti (
    id INT PRIMARY KEY REFERENCES clienti(id),
    saldo NUMERIC(15,2) CHECK (saldo >= 0),
    numero_conto TEXT NOT NULL UNIQUE,
    data_apertura DATE NOT NULL
);
